"""Field descriptors for the ORM."""
from typing import Any, Optional


class Field:
    """Base field descriptor."""
    def __init__(self, field_type: type, primary_key: bool = False, nullable: bool = True):
        self.field_type = field_type
        self.primary_key = primary_key
        self.nullable = nullable
        self.name: Optional[str] = None

    def __set_name__(self, owner, name: str):
        self.name = name

    def validate(self, value: Any) -> Any:
        """Coerce and validate value."""
        if value is None and not self.nullable:
            raise ValueError(f"{self.name}: value cannot be None")
        if value is not None and not isinstance(value, self.field_type):
            value = self.field_type(value)
        return value


class IntField(Field):
    def __init__(self, primary_key: bool = False, nullable: bool = False):
        super().__init__(int, primary_key=primary_key, nullable=nullable)


class StrField(Field):
    def __init__(self, nullable: bool = False):
        super().__init__(str, nullable=nullable)

