"""Base Model class for the mini ORM."""
from typing import Any, ClassVar, Optional, Type, TypeVar
from orm.fields import Field

T = TypeVar('T', bound='Model')


class ModelMeta(type):
    """Metaclass: collect Field descriptors into _fields."""
    def __new__(mcs, name, bases, namespace):
        fields: dict[str, Field] = {}
        for key, val in namespace.items():
            if isinstance(val, Field):
                fields[key] = val
        namespace['_fields'] = fields
        return super().__new__(mcs, name, bases, namespace)


class Model(metaclass=ModelMeta):
    _fields: ClassVar[dict[str, Field]]
    _table: ClassVar[list]  # in-memory storage
    _next_id: ClassVar[int] = 1

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls._table = []
        cls._next_id = 1

    def __init__(self, **kwargs):
        for name, field in self._fields.items():
            value = kwargs.get(name)
            setattr(self, f'_{name}', field.validate(value))
        if not hasattr(self, '_id_val'):
            self._id_val = None

    def save(self) -> 'Model':
        """Save model to in-memory store. Assigns ID if new."""
        raise NotImplementedError

    @classmethod
    def create(cls: Type[T], **kwargs) -> T:
        """Create and immediately save a model instance."""
        raise NotImplementedError

    @classmethod
    def all(cls: Type[T]) -> list[T]:
        """Return all saved instances."""
        raise NotImplementedError

    @classmethod
    def filter(cls: Type[T], **kwargs) -> list[T]:
        """Return instances matching all keyword filters."""
        raise NotImplementedError

    @classmethod
    def get(cls: Type[T], **kwargs) -> Optional[T]:
        """Return first matching instance or None."""
        raise NotImplementedError

    def __repr__(self) -> str:
        fields = ', '.join(f'{k}={getattr(self, "_" + k, None)!r}' for k in self._fields)
        return f'{self.__class__.__name__}({fields})'
